(function () {
  var t = "light";
  try { t = localStorage.getItem("aps_kit_theme") || "light"; } catch (e) {}
  if (t !== "dark" && t !== "light") t = "light";
  document.documentElement.setAttribute("data-theme", t);
})();

(function () {
  var theme = 'light';
  try { theme = localStorage.getItem('aps_kit_theme') || 'light'; } catch (error) { console.error('读取主题偏好失败：', error); }
  document.documentElement.setAttribute('data-theme', theme === 'dark' ? 'dark' : 'light');
})();
